import { Canvas, useFrame } from '@react-three/fiber'
import { Html, Line, OrbitControls } from '@react-three/drei'
import { useEffect, useMemo, useRef, useState, type ComponentRef } from 'react'
import * as THREE from 'three'
import type { AirCityRecord, AirMetric, CityKey } from '../data/ecology'
import { getCityGeo, guizhouCities, guizhouTerrain } from '../data/guizhouGeo'
import { useMotionProfile, type MotionProfile } from '../hooks/useMotionProfile'
import {
  TERRAIN_SCENE_DEPTH,
  TERRAIN_SCENE_WIDTH,
  decodeElevation,
  elevationToScene,
  loadGuizhouDem,
  normalizedHeightToScene,
  projectLngLat,
  sampleDem,
  visibleParticleCount,
  type GuizhouDemGrid,
} from './guizhouTerrainMath'

export interface GuizhouTerrain3DProps {
  records: AirCityRecord[]
  metric: AirMetric
  selectedCity: CityKey
  scanning: boolean
  focusSignal: number
  resetViewSignal: number
  onSelectCity: (city: CityKey) => void
}

const hash = (x: number, y: number) => {
  const value = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return value - Math.floor(value)
}

const surfaceVertexShader = `
  attribute float aElevation;
  attribute float aSlope;
  attribute float aRandom;
  uniform float uTime;
  uniform float uPointScale;
  uniform float uMotion;
  varying float vElevation;
  varying float vSlope;
  varying float vRandom;
  void main() {
    vElevation = aElevation;
    vSlope = aSlope;
    vRandom = aRandom;
    vec3 displaced = position;
    displaced.y += sin(uTime * 0.52 + aRandom * 20.0) * 0.006 * uMotion;
    vec4 mvPosition = modelViewMatrix * vec4(displaced, 1.0);
    gl_Position = projectionMatrix * mvPosition;
    gl_PointSize = clamp(uPointScale * (0.78 + aSlope * 0.5 + aRandom * 0.14) / max(1.0, -mvPosition.z), 1.05, 4.2);
  }
`

const surfaceFragmentShader = `
  varying float vElevation;
  varying float vSlope;
  varying float vRandom;
  void main() {
    vec2 center = gl_PointCoord - vec2(0.5);
    float radius = length(center);
    if (radius > 0.5) discard;
    float alpha = smoothstep(0.5, 0.08, radius);
    vec3 cyan = vec3(0.0, 0.72, 0.80);
    vec3 green = vec3(0.27, 1.0, 0.47);
    vec3 lime = vec3(0.80, 1.0, 0.22);
    vec3 gold = vec3(1.0, 0.85, 0.30);
    vec3 orange = vec3(1.0, 0.55, 0.23);
    vec3 color = mix(cyan, green, smoothstep(0.02, 0.30, vElevation));
    color = mix(color, lime, smoothstep(0.26, 0.50, vElevation));
    color = mix(color, gold, smoothstep(0.48, 0.70, vElevation));
    color = mix(color, orange, smoothstep(0.72, 0.96, vElevation));
    float interval = fract(vElevation * 14.0);
    float contour = 1.0 - smoothstep(0.0, 0.075, min(interval, 1.0 - interval));
    color += vec3(0.35, 0.42, 0.16) * contour * (0.22 + vSlope * 0.34);
    color *= 0.76 + vRandom * 0.25 + vSlope * 0.18;
    gl_FragColor = vec4(color, alpha * 0.94);
  }
`

function createTerrainGeometry(grid: GuizhouDemGrid, stride: number) {
  const count = visibleParticleCount(grid, stride)
  const positions = new Float32Array(count * 3)
  const elevations = new Float32Array(count)
  const slopes = new Float32Array(count)
  const randoms = new Float32Array(count)
  let target = 0
  for (let row = 0; row < grid.height; row += stride) {
    for (let column = 0; column < grid.width; column += stride) {
      const encoded = grid.values[row * grid.width + column]
      const elevation = decodeElevation(encoded, grid)
      if (elevation === null) continue
      const longitude = grid.bounds.minLon + column / (grid.width - 1) * (grid.bounds.maxLon - grid.bounds.minLon)
      const latitude = grid.bounds.maxLat - row / (grid.height - 1) * (grid.bounds.maxLat - grid.bounds.minLat)
      const projected = projectLngLat(longitude, latitude)
      const normalized = (elevation - grid.minimum) / Math.max(1, grid.maximum - grid.minimum)
      const right = decodeElevation(grid.values[row * grid.width + Math.min(grid.width - 1, column + stride)], grid) ?? elevation
      const down = decodeElevation(grid.values[Math.min(grid.height - 1, row + stride) * grid.width + column], grid) ?? elevation
      const slope = Math.min(1, Math.hypot(right - elevation, down - elevation) / 160)
      positions[target * 3] = projected.x
      positions[target * 3 + 1] = normalizedHeightToScene(normalized)
      positions[target * 3 + 2] = projected.z
      elevations[target] = normalized
      slopes[target] = slope
      randoms[target] = hash(column, row)
      target += 1
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  geometry.setAttribute('aElevation', new THREE.BufferAttribute(elevations, 1))
  geometry.setAttribute('aSlope', new THREE.BufferAttribute(slopes, 1))
  geometry.setAttribute('aRandom', new THREE.BufferAttribute(randoms, 1))
  geometry.computeBoundingSphere()
  return geometry
}

function createSkirtGeometry(grid: GuizhouDemGrid, stride: number) {
  const boundary = guizhouTerrain.boundary.filter((_, index) => index % stride === 0)
  const levels = 10
  const positions: number[] = []
  const elevations: number[] = []
  const slopes: number[] = []
  const randoms: number[] = []
  boundary.forEach(([longitude, latitude], index) => {
    const projected = projectLngLat(longitude, latitude)
    const elevation = sampleDem(grid, longitude, latitude)
    const top = elevationToScene(elevation, grid)
    for (let level = 0; level < levels; level += 1) {
      const t = level / (levels - 1)
      positions.push(projected.x, THREE.MathUtils.lerp(top, -1.36, t), projected.z)
      elevations.push(Math.max(0, (elevation - grid.minimum) / Math.max(1, grid.maximum - grid.minimum)) * (1 - t * .75))
      slopes.push(.18)
      randoms.push(hash(index, level))
    }
  })
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geometry.setAttribute('aElevation', new THREE.Float32BufferAttribute(elevations, 1))
  geometry.setAttribute('aSlope', new THREE.Float32BufferAttribute(slopes, 1))
  geometry.setAttribute('aRandom', new THREE.Float32BufferAttribute(randoms, 1))
  return geometry
}

function TerrainParticles({ grid, profile, skirt = false }: { grid: GuizhouDemGrid; profile: MotionProfile; skirt?: boolean }) {
  const stride = profile === 'full' ? 1 : profile === 'lite' ? 2 : 3
  const geometry = useMemo(() => skirt ? createSkirtGeometry(grid, profile === 'full' ? 1 : 2) : createTerrainGeometry(grid, stride), [grid, profile, skirt, stride])
  const material = useMemo(() => new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uPointScale: { value: profile === 'full' ? 28 : profile === 'lite' ? 26 : 23 },
      uMotion: { value: profile === 'reduced' ? 0 : 1 },
    },
    vertexShader: surfaceVertexShader,
    fragmentShader: surfaceFragmentShader,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }), [profile])
  useFrame((state) => { material.uniforms.uTime.value = state.clock.elapsedTime })
  useEffect(() => () => { geometry.dispose(); material.dispose() }, [geometry, material])
  return <points geometry={geometry} material={material} frustumCulled={false} />
}

function ProvinceOutline({ grid }: { grid: GuizhouDemGrid }) {
  const points = useMemo(() => guizhouTerrain.boundary.map(([longitude, latitude]) => {
    const projected = projectLngLat(longitude, latitude)
    return [projected.x, elevationToScene(sampleDem(grid, longitude, latitude), grid) + .045, projected.z] as [number, number, number]
  }), [grid])
  return <Line points={points} color="#CBFF38" lineWidth={.8} transparent opacity={.68} />
}

function CityBeacon({ grid, record, metric, selected, scanning, onSelect }: {
  grid: GuizhouDemGrid
  record: AirCityRecord
  metric: AirMetric
  selected: boolean
  scanning: boolean
  onSelect: () => void
}) {
  const group = useRef<THREE.Group>(null)
  const geo = getCityGeo(record.city)
  const projected = projectLngLat(geo.longitude, geo.latitude)
  const ground = elevationToScene(sampleDem(grid, geo.longitude, geo.latitude), grid) + .06
  const accent = metric === 'pm25' ? '#CBFF38' : '#69D6C5'
  const labelPosition: [number, number, number] = [geo.labelOffset[0], .98, geo.labelOffset[1]]

  useFrame((state) => {
    if (!group.current) return
    const speed = scanning ? 7 : 2.4
    const pulse = 1 + Math.sin(state.clock.elapsedTime * speed + geo.longitude) * (selected ? .12 : .045)
    group.current.scale.setScalar(pulse)
  })

  return (
    <group position={[projected.x, ground, projected.z]}>
      <group ref={group}>
        <mesh rotation={[-Math.PI / 2, 0, 0]} onClick={(event) => { event.stopPropagation(); onSelect() }}>
          <ringGeometry args={[selected ? .12 : .075, selected ? .165 : .105, 32]} />
          <meshBasicMaterial color={selected ? '#FAF7EF' : accent} transparent opacity={selected ? 1 : .72} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
        </mesh>
        <mesh position={[0, .39, 0]}>
          <cylinderGeometry args={[.008, .015, .78, 8]} />
          <meshBasicMaterial color={accent} transparent opacity={selected || scanning ? .94 : .5} blending={THREE.AdditiveBlending} />
        </mesh>
        <mesh position={[0, .8, 0]}>
          <sphereGeometry args={[selected ? .055 : .035, 12, 12]} />
          <meshBasicMaterial color={selected ? '#FAF7EF' : accent} blending={THREE.AdditiveBlending} />
        </mesh>
      </group>
      <Line points={[[0, .82, 0], labelPosition]} color={accent} lineWidth={.45} transparent opacity={selected ? .8 : .34} />
      <Html position={labelPosition} center distanceFactor={8.6} zIndexRange={[12, 0]}>
        <button
          type="button"
          className={`geo-city-label ${selected ? 'is-selected' : ''}`}
          onClick={(event) => { event.stopPropagation(); onSelect() }}
          aria-label={`飞往${record.city}，${metric === 'pm25' ? 'PM2.5' : 'PM10'} ${record[metric]}微克每立方米`}
        >
          <span>{geo.code} / {geo.nameEn}</span>
          <strong>{record.city.replace('市', '')}</strong>
          <em>{record[metric]}<small> μg/m³</small></em>
        </button>
      </Html>
    </group>
  )
}

function ScanSweep({ scanning, profile }: { scanning: boolean; profile: MotionProfile }) {
  const group = useRef<THREE.Group>(null)
  const startedAt = useRef(0)
  useEffect(() => { if (scanning) startedAt.current = performance.now() / 1000 }, [scanning])
  useFrame(() => {
    if (!group.current || !scanning) return
    const elapsed = performance.now() / 1000 - startedAt.current
    const progress = Math.min(1, elapsed / 4.6)
    group.current.position.z = -TERRAIN_SCENE_DEPTH / 2 + progress * TERRAIN_SCENE_DEPTH
  })
  if (!scanning || profile === 'reduced') return null
  return (
    <group ref={group} position={[0, 0, -TERRAIN_SCENE_DEPTH / 2]}>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 2.72, 0]}>
        <planeGeometry args={[TERRAIN_SCENE_WIDTH + .8, .13]} />
        <meshBasicMaterial color="#CBFF38" transparent opacity={.92} depthWrite={false} blending={THREE.AdditiveBlending} />
      </mesh>
      <mesh position={[0, .7, 0]}>
        <planeGeometry args={[TERRAIN_SCENE_WIDTH + .8, 4.1]} />
        <meshBasicMaterial color="#69D6C5" transparent opacity={.055} depthWrite={false} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  )
}

function CameraRig({ grid, selectedCity, focusSignal, resetViewSignal, profile }: {
  grid: GuizhouDemGrid
  selectedCity: CityKey
  focusSignal: number
  resetViewSignal: number
  profile: MotionProfile
}) {
  const controls = useRef<ComponentRef<typeof OrbitControls>>(null)
  const desiredPosition = useRef<THREE.Vector3 | null>(null)
  const desiredTarget = useRef<THREE.Vector3 | null>(null)
  const defaultPosition = useMemo(() => new THREE.Vector3(8.4, 7.1, 9.6), [])
  const defaultTarget = useMemo(() => new THREE.Vector3(0, .25, 0), [])

  useEffect(() => {
    if (!focusSignal) return
    const geo = getCityGeo(selectedCity)
    const projected = projectLngLat(geo.longitude, geo.latitude)
    const y = elevationToScene(sampleDem(grid, geo.longitude, geo.latitude), grid)
    desiredTarget.current = new THREE.Vector3(projected.x, y + .25, projected.z)
    desiredPosition.current = new THREE.Vector3(projected.x + 4.8, y + 4.4, projected.z + 5.8)
  }, [focusSignal, grid, selectedCity])

  useEffect(() => {
    desiredTarget.current = defaultTarget.clone()
    desiredPosition.current = defaultPosition.clone()
  }, [resetViewSignal, defaultPosition, defaultTarget])

  useFrame((state, delta) => {
    if (!desiredPosition.current || !desiredTarget.current || !controls.current) return
    const alpha = 1 - Math.exp(-delta * (profile === 'reduced' ? 10 : 3.8))
    state.camera.position.lerp(desiredPosition.current, alpha)
    controls.current.target.lerp(desiredTarget.current, alpha)
    controls.current.update()
    if (state.camera.position.distanceTo(desiredPosition.current) < .025 && controls.current.target.distanceTo(desiredTarget.current) < .025) {
      desiredPosition.current = null
      desiredTarget.current = null
    }
  })

  return (
    <OrbitControls
      ref={controls}
      makeDefault
      enablePan={false}
      enableDamping
      dampingFactor={.065}
      minDistance={5.6}
      maxDistance={16}
      minPolarAngle={.46}
      maxPolarAngle={1.38}
      target={[0, .25, 0]}
    />
  )
}

function Scene({ grid, profile, props }: { grid: GuizhouDemGrid; profile: MotionProfile; props: GuizhouTerrain3DProps }) {
  return (
    <>
      <color attach="background" args={['#030604']} />
      <fog attach="fog" args={['#030604', 10, 23]} />
      <ambientLight intensity={.24} />
      <pointLight position={[-2, 8, 3]} intensity={2.2} color="#CBFF38" distance={18} />
      <TerrainParticles grid={grid} profile={profile} />
      <TerrainParticles grid={grid} profile={profile} skirt />
      <ProvinceOutline grid={grid} />
      {props.records.map((record) => (
        <CityBeacon
          key={record.city}
          grid={grid}
          record={record}
          metric={props.metric}
          selected={record.city === props.selectedCity}
          scanning={props.scanning}
          onSelect={() => props.onSelectCity(record.city)}
        />
      ))}
      <ScanSweep scanning={props.scanning} profile={profile} />
      <gridHelper args={[18, 36, '#234b38', '#0b1a12']} position={[0, -1.38, 0]} />
      <CameraRig grid={grid} selectedCity={props.selectedCity} focusSignal={props.focusSignal} resetViewSignal={props.resetViewSignal} profile={profile} />
    </>
  )
}

const supportsWebGL = () => {
  try {
    const canvas = document.createElement('canvas')
    return Boolean(canvas.getContext('webgl2') || canvas.getContext('webgl'))
  } catch {
    return false
  }
}

export function GuizhouTerrain3D(props: GuizhouTerrain3DProps) {
  const profile = useMotionProfile()
  const [grid, setGrid] = useState<GuizhouDemGrid | null>(null)
  const [error, setError] = useState(false)
  const [webgl, setWebgl] = useState<boolean | null>(null)

  useEffect(() => setWebgl(supportsWebGL()), [])
  useEffect(() => {
    const controller = new AbortController()
    loadGuizhouDem(controller.signal).then(setGrid).catch((reason) => {
      if (reason?.name !== 'AbortError') setError(true)
    })
    return () => controller.abort()
  }, [])

  const stride = profile === 'full' ? 1 : profile === 'lite' ? 2 : 3
  const pointCount = grid ? visibleParticleCount(grid, stride) : 0
  return (
    <div className={`guizhou-terrain-3d motion-${profile} ${props.scanning ? 'is-scanning' : ''}`} role="img" aria-label="贵州省真实DEM三维粒子地形与九个中心城市数据定位索引">
      {grid && webgl ? (
        <Canvas
          aria-hidden="true"
          dpr={profile === 'full' ? [1, 1.45] : 1}
          camera={{ position: [8.4, 7.1, 9.6], fov: 38, near: .1, far: 40 }}
          gl={{ antialias: profile === 'full', alpha: false, powerPreference: 'high-performance' }}
        >
          <Scene grid={grid} profile={profile} props={props} />
        </Canvas>
      ) : (
        <div className={`geo-terrain-loader ${error || webgl === false ? 'is-error' : ''}`}>
          <span />
          <strong>{error || webgl === false ? '3D地形暂不可用' : '正在装载贵州高程数据'}</strong>
          <small>{error || webgl === false ? '已保留右侧真实数据与城市切换功能' : 'COPERNICUS DEM / LOCAL ASSET'}</small>
        </div>
      )}
      <div className="geo-screen-grid" aria-hidden="true" />
      <div className="geo-vignette" aria-hidden="true" />
      <p className="geo-dem-note">
        {pointCount ? `${pointCount.toLocaleString()} VISIBLE POINTS` : 'LOADING DEM'} · COPERNICUS GLO-30 · 高程2.2×视觉增强
      </p>
    </div>
  )
}

export { guizhouCities }

